def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def hasact(adm, prefix, target, dest, verb):
    for a in adm or []:
        s = text(a)
        if s.startswith(prefix) and (not target or target in s) and (not dest or dest in s) and (not verb or verb in s):
            return True
    return False

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(val(ctx, 'world.inventory', ''))
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['carrying_target'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['carrying_target'] = False
    if target and verb and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs:
        nb['transformed'] = True
    pc = val(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if target and act.startswith('put ') and target in act and 'you put' in obs and dest and dest in act:
        if pc < nb.get('placed_count', 0) + 1:
            pc = nb.get('placed_count', 0) + 1
    nb['placed_count'] = pc
    adm = ctx.get('admissible', []) or []
    inv_nonempty = bool(inv) and 'nothing' not in inv and 'not carrying' not in inv and 'empty' not in inv
    carrying = bool(nb.get('carrying_target')) or (target and target in inv)
    wrong = bool(inv_nonempty and target and not carrying)
    take_ready = bool(target and hasact(adm, 'take ', target, '', ''))
    put_ready = bool(target and dest and hasact(adm, 'put ', target, dest, ''))
    trans_ready = bool(target and verb and not nb.get('transformed') and hasact(adm, verb + ' ', target, '', ''))
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and verb and not nb.get('transformed'):
        stage = 'transform'
    elif carrying and put_ready:
        stage = 'put_target'
    elif carrying:
        stage = 'go_destination'
    elif take_ready:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

