def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(val(ctx, 'task.task_type', ''))
    tt = nb.get('task_type') or text(val(ctx, 'task.task_type', ''))
    adm = ctx.get('admissible', []) or []
    take_ready = bool(target and any(a.startswith('take ') and target in text(a) for a in adm))
    trans_ready = bool(target and verb and not nb.get('transformed') and any(a.startswith(verb + ' ') and target in text(a) for a in adm))
    put_ready = bool(target and dest and any(a.startswith('put ') and target in text(a) and dest in text(a) for a in adm))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type; do not place it at the destination. Recover by setting it aside if needed, then search for the target.'
    elif stage == 'take_target' and take_ready:
        msg = 'A requested target object is available here; take it now instead of continuing to search.'
    elif stage == 'transform' and verb:
        if trans_ready:
            msg = 'The required ' + verb + ' action is available for the carried target; do it before placing.'
        else:
            place = 'sinkbasin'
            if verb == 'heat':
                place = 'microwave'
            if verb == 'cool':
                place = 'fridge'
            if verb == 'slice':
                place = 'knife'
            msg = 'Carry the target to a ' + place + ' and use the ' + verb + ' action before going to the destination.'
    elif stage == 'put_target' and put_ready:
        msg = 'You are at the requested destination with the target; use the put action now.'
    elif stage == 'go_destination' and dest:
        msg = 'Carry the target to a ' + dest + ' and put it there; do not put it on other receptacles.'
    elif stage == 'find_target' and 'two' in tt and nb.get('placed_count', 0) > 0:
        msg = 'One target is already placed; leave it there and find another target of the same type for the same destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

