def hook(ctx, nb):
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type') or text(val(ctx, 'task.task_type', ''))
    verb = nb.get('required_verb') or needverb(tt)
    if not target:
        return None
    adm = ctx.get('admissible', []) or []
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    inv = text(val(ctx, 'world.inventory', ''))
    carrying = bool(nb.get('carrying_target')) or (target in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and 'empty' not in inv and not carrying)
    if wrong and act.startswith('put ') and dest and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested target type. Do not place it at the destination; recover by finding the target object.'}
    if not carrying and act.startswith('take ') and target in act and dest and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'Do not take a target from the destination. Search other containers or surfaces for the target.'}
    if not carrying and act.startswith('take ') and target in act and 'two' in tt and nb.get('placed_count', 0) > 0:
        locs = text(val(ctx, 'world.placed_locations', ''))
        if locs and locs in act:
            return {'kind': 'block_and_prompt', 'message': 'Leave already placed targets at the destination; find another target of the same type.'}
    if carrying and verb and not nb.get('transformed') and act.startswith('put ') and target in act and dest and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First use the required ' + verb + ' action, then put it at the destination.'}
    if carrying and verb and not nb.get('transformed') and act.startswith('put ') and target in act and not (dest and dest in act):
        return {'kind': 'block_and_prompt', 'message': 'Do not put the target on a non-destination receptacle. Carry it to the required destination after transforming it.'}
    if carrying and verb and not nb.get('transformed') and hasact(adm, verb + ' ', target, '', '') and not (act.startswith(verb + ' ') and target in act):
        return {'kind': 'block_and_prompt', 'message': 'The required transform action is available now. Use it on the carried target before navigating away.'}
    if carrying and dest and hasact(adm, 'put ', target, dest, '') and not (act.startswith('put ') and target in act and dest in act):
        return {'kind': 'block_and_prompt', 'message': 'The destination put action is available now. Put the carried target at the requested destination instead of continuing to search.'}
    return None
